"use client";

import { useEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { RocketLaunchIcon as PhRocket, ArrowCounterClockwiseIcon as PhReset } from "@phosphor-icons/react";

interface WaitingStep {
  label: string;
  typicalMs: number;
  actualMs: number;
}

const STEPS: WaitingStep[] = [
  { label: "Uploading files", typicalMs: 1400, actualMs: 1300 },
  { label: "Building assets", typicalMs: 2200, actualMs: 3600 },
  { label: "Running checks", typicalMs: 1100, actualMs: 1000 },
  { label: "Going live", typicalMs: 900, actualMs: 850 },
];

const ACTUAL_DURATIONS = STEPS.map((s) => s.actualMs);
const REDUCED_DURATIONS = STEPS.map(() => 80);
const OVERRUN_BUFFER_MS = 500;

function RocketIcon() {
  return <PhRocket size={13} weight="fill" aria-hidden />;
}

function ResetIcon() {
  return <PhReset size={13} aria-hidden />;
}

function CheckIcon({ size = 11 }: { size?: number }) {
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <motion.path d="M20 6 9 17l-5-5" initial={{ pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }} />
    </svg>
  );
}

function formatElapsed(ms: number) {
  return `${(ms / 1000).toFixed(1)}s`;
}

function StepIndicator({ status, shouldReduceMotion }: { status: "pending" | "active" | "done"; shouldReduceMotion: boolean | null }) {
  if (status === "done") {
    return (
      <span className="relative flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-600 text-white">
        <CheckIcon />
      </span>
    );
  }
  if (status === "active") {
    return (
      <span className="relative flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-emerald-500/15">
        <motion.span
          aria-hidden
          className="absolute inset-0 rounded-full border-2 border-emerald-400/25 border-t-emerald-500"
          animate={shouldReduceMotion ? { rotate: 0 } : { rotate: 360 }}
          transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.8, repeat: Infinity, ease: "linear" }}
        />
        <span className="h-1.5 w-1.5 rounded-full bg-emerald-500" />
      </span>
    );
  }
  return <span className="h-6 w-6 shrink-0 rounded-full border-2 border-slate-200 dark:border-slate-700" />;
}

function WaitingStateRun({ onReplay }: { onReplay: () => void }) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [finished, setFinished] = useState(false);
  const [elapsedMs, setElapsedMs] = useState(0);
  const [overrunning, setOverrunning] = useState(false);
  const startRef = useRef(0);
  const shouldReduceMotion = useReducedMotion();

  useEffect(() => {
    startRef.current = performance.now();
    const durations = shouldReduceMotion ? REDUCED_DURATIONS : ACTUAL_DURATIONS;
    let cumulative = 0;
    let cancelled = false;
    const timeouts: ReturnType<typeof setTimeout>[] = [];

    durations.forEach((d, i) => {
      cumulative += d;
      timeouts.push(
        setTimeout(() => {
          if (cancelled) return;
          if (i === durations.length - 1) {
            setFinished(true);
          } else {
            setCurrentIndex(i + 1);
          }
        }, cumulative)
      );
    });

    return () => {
      cancelled = true;
      timeouts.forEach(clearTimeout);
    };
  }, [shouldReduceMotion]);

  useEffect(() => {
    if (finished) return;
    let raf: number;
    const durations = shouldReduceMotion ? REDUCED_DURATIONS : ACTUAL_DURATIONS;
    const stepStart = durations.slice(0, currentIndex).reduce((sum, d) => sum + d, 0);
    const typical = shouldReduceMotion ? REDUCED_DURATIONS[currentIndex] : STEPS[currentIndex].typicalMs;
    const buffer = shouldReduceMotion ? 0 : OVERRUN_BUFFER_MS;

    const tick = () => {
      const elapsed = performance.now() - startRef.current;
      setElapsedMs(elapsed);
      setOverrunning(elapsed - stepStart > typical + buffer);
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [finished, currentIndex, shouldReduceMotion]);

  const statusOf = (i: number): "pending" | "active" | "done" => (i < currentIndex || (i === currentIndex && finished) ? "done" : i === currentIndex ? "active" : "pending");

  return (
    <div className="relative w-full max-w-md">
      <div className="relative rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <div className="flex items-center gap-2.5">
          <span
            className={`relative flex h-7 w-7 shrink-0 items-center justify-center rounded-full transition-colors duration-300 ${
              finished ? "bg-emerald-600 text-white" : "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400"
            }`}
          >
            {finished && !shouldReduceMotion && (
              <motion.span
                aria-hidden
                className="absolute inset-0 rounded-full border-2 border-emerald-400/60"
                initial={{ scale: 0.7, opacity: 0.9 }}
                animate={{ scale: 1.7, opacity: 0 }}
                transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
              />
            )}
            {finished ? (
              <CheckIcon size={13} />
            ) : (
              <motion.span animate={shouldReduceMotion ? { y: 0 } : { y: [0, -1.5, 0] }} transition={{ duration: 1.6, repeat: Infinity, ease: "easeInOut" }}>
                <RocketIcon />
              </motion.span>
            )}
          </span>
          <h3 className="flex-1 text-sm font-semibold text-slate-900 dark:text-white">{finished ? `Live in ${formatElapsed(elapsedMs)}` : "Deploying your site"}</h3>
          {!finished && <span className="shrink-0 tabular-nums text-xs text-slate-400 dark:text-slate-500">{formatElapsed(elapsedMs)}</span>}
          {finished && (
            <motion.button
              type="button"
              onClick={onReplay}
              aria-label="Deploy again"
              whileTap={shouldReduceMotion ? undefined : { scale: 0.9 }}
              className="inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
            >
              <ResetIcon />
            </motion.button>
          )}
        </div>

        <div className="mt-4">
          {STEPS.map((step, i) => {
            const status = statusOf(i);
            return (
              <div key={step.label} className="flex gap-3">
                <div className="flex flex-col items-center">
                  <StepIndicator status={status} shouldReduceMotion={shouldReduceMotion} />
                  {i < STEPS.length - 1 && (
                    <span className="relative my-1 w-px flex-1 bg-slate-200 dark:bg-slate-700">
                      <motion.span
                        aria-hidden
                        className="absolute inset-0 origin-top bg-emerald-500"
                        initial={{ scaleY: 0 }}
                        animate={{ scaleY: status === "done" ? 1 : 0 }}
                        transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
                      />
                    </span>
                  )}
                </div>
                <div className="flex-1 pb-4 last:pb-0">
                  <div className="flex items-center justify-between gap-2 pt-0.5">
                    <p className={`text-sm font-medium transition-colors ${status === "pending" ? "text-slate-400 dark:text-slate-600" : "text-slate-800 dark:text-slate-100"}`}>
                      {step.label}
                    </p>
                    {status === "done" && <span className="shrink-0 tabular-nums text-xs text-slate-400 dark:text-slate-500">{formatElapsed(step.actualMs)}</span>}
                  </div>
                  <AnimatePresence>
                    {status === "active" && overrunning && (
                      <motion.p
                        initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
                        transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
                        className="mt-1 flex items-center gap-1.5 text-xs text-amber-600 dark:text-amber-400"
                      >
                        <motion.span
                          aria-hidden
                          className="h-1.5 w-1.5 shrink-0 rounded-full bg-amber-500"
                          animate={shouldReduceMotion ? { opacity: 0.7 } : { opacity: [0.4, 1, 0.4] }}
                          transition={shouldReduceMotion ? { duration: 0.2 } : { duration: 1.4, repeat: Infinity, ease: "easeInOut" }}
                        />
                        Taking a little longer than usual, still going.
                      </motion.p>
                    )}
                  </AnimatePresence>
                </div>
              </div>
            );
          })}
        </div>

        <span className="sr-only" role="status" aria-live="polite">
          {finished
            ? `Deployed. Total time ${formatElapsed(elapsedMs)}.`
            : overrunning
              ? `${STEPS[currentIndex].label} is taking longer than usual, still in progress.`
              : `Step ${currentIndex + 1} of ${STEPS.length}: ${STEPS[currentIndex].label}.`}
        </span>
      </div>
    </div>
  );
}
